// Standard uncompressed RGB PSD, flattened composite, 8 bits per channel.
function makePSD(w,h,rgba){const n=w*h,out=new Uint8Array(40+n*3),d=new DataView(out.buffer);out.set([56,66,80,83]);d.setUint16(4,1);d.setUint16(12,3);d.setUint32(14,h);d.setUint32(18,w);d.setUint16(22,8);d.setUint16(24,3);for(let c=0;c<3;c++)for(let p=0;p<n;p++)out[40+c*n+p]=rgba[p*4+c];return out}
// One-page PDF with an embedded high-resolution JPEG and byte-accurate xref.
function makePDF(jpg,w,h){const enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const put=x=>{const b=typeof x==='string'?enc.encode(x):x;parts.push(b);length+=b.length};const pw=w>=h?842:595,ph=w>=h?595:842,scale=Math.min((pw-40)/w,(ph-40)/h),iw=w*scale,ih=h*scale;put('%PDF-1.4\n');const obj=(i,s)=>{offsets[i]=length;put(i+' 0 obj\n'+s+'\nendobj\n')};obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=length;put(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);put(jpg);put('\nendstream\nendobj\n');const stream=`q\n${iw} 0 0 ${ih} ${(pw-iw)/2} ${(ph-ih)/2} cm\n/Im0 Do\nQ\n`;obj(5,`<< /Length ${enc.encode(stream).length} >>\nstream\n${stream}endstream`);const start=length;put('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<6;i++)put(String(offsets[i]).padStart(10,'0')+' 00000 n \n');put(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`);const result=new Uint8Array(length);let at=0;for(const p of parts){result.set(p,at);at+=p.length}return result}
